-- Built-in aura icon skins (data only; the painter is MSUF_Auras3_IconSkins.lua).
-- Display names are localized. Registration IDs are used by profiles and the host API.
-- Every texture under Media/Skins is generated by tools/generate_aura_icon_skins.py
-- from closed-form profiles; Blizzard art is referenced by its own atlas or
-- path and never shipped. Band spans (`outer`/`inner`, in u = 1/32 of the icon
-- side) must match the generator's profiles; quad extents likewise.
-- tools/tests/aura_icon_skin_media_smoke.py checks both.
local _, MSUF = ...
local A3 = assert(MSUF.MSUF_Auras3)
local Skins = assert(A3.IconSkins)
local MSUF_MEDIA = A3.IconShape.MEDIA_ROOT .. "\\Media\\"

local WHITE = { 1, 1, 1, 1 }
local GLOSS_CRESCENT = "msuf_skin_gloss_crescent"
local GLOSS_TOP = { file = "msuf_skin_gloss_top", enabled = true }
local GLOSS_DOME = { file = "msuf_skin_gloss_dome", enabled = true }
local GLOSS_GLASS = { file = "msuf_skin_glass_gloss", enabled = true }
local GLOSS_OFF = { file = "msuf_skin_gloss_top", enabled = false }

local function Shadow(alpha)
    return { kind = "band", file = "msuf_skin_shadow_outer", outer = 4, inner = 0, color = { 0, 0, 0, alpha }, tint = false }
end
local function RoundShadow(alpha)
    return { kind = "quad", file = "msuf_skin_shadow_round", extent = 5, color = { 0, 0, 0, alpha }, tint = false }
end
local function Line(px, place, color, tint)
    return { kind = "line", px = px, place = place, color = color, tint = tint }
end

-- Shadow: soft outer shadow, inner vignette, frame line.
Skins.Register("SHADOW1", {
    text = "Glossy Shadow",
    gloss = { file = GLOSS_CRESCENT, enabled = true },
    layers = {
        { kind = "band", file = "msuf_skin_shadow_soft", outer = 4, inner = 10 },
        { kind = "line", width = 1, place = "inside" },
    },
})
Skins.Register("SHADOW2", {
    text = "Inner Shade",
    gloss = { file = GLOSS_CRESCENT, enabled = false },
    layers = { { kind = "band", file = "msuf_skin_shadow_hard", outer = 0, inner = 13 } },
})
Skins.Register("SHADOW3", {
    text = "Inner & Outer Shade",
    gloss = { file = GLOSS_CRESCENT, enabled = false },
    layers = {
        { kind = "band", file = "msuf_skin_shadow_outer", outer = 4, inner = 0 },
        { kind = "band", file = "msuf_skin_shadow_hard", outer = 0, inner = 13 },
    },
    variants = {
        CIRCLE = {
            gloss = { file = GLOSS_DOME.file, enabled = false },
            layers = { { kind = "quad", file = "msuf_skin_shadow3_circle", extent = 4 } },
        },
    },
})
Skins.Register("SHADOW4", {
    text = "Glossy Hairline",
    gloss = { file = "msuf_skin_gloss_sheen", enabled = true },
    layers = { Line(1, "inside") },
})
Skins.Register("SHADOW5", {
    text = "Soft Edge Shadow",
    gloss = { file = GLOSS_CRESCENT, enabled = false },
    layers = { { kind = "band", file = "msuf_skin_shadow_ring", outer = 3.75, inner = 5 } },
})

-- Dark: inner vignettes with a one-pixel outline outside the icon.
local function Dark(id, text, band, inner, dim)
    local layers = {}
    if dim then layers[#layers + 1] = { kind = "dim", alpha = dim } end
    layers[#layers + 1] = { kind = "band", file = band, outer = 0, inner = inner }
    layers[#layers + 1] = Line(1, "outside")
    Skins.Register(id, { text = text, gloss = { file = GLOSS_CRESCENT, enabled = false }, layers = layers })
end
Dark("DARK1", "Crisp Vignette", "msuf_skin_vignette_crisp", 9)
Dark("DARK2", "Soft Vignette", "msuf_skin_vignette_soft", 14)
Dark("DARK3", "Deep Vignette", "msuf_skin_vignette_heavy", 11, 0.30)
Dark("DARK4", "Dim Vignette", "msuf_skin_vignette_heavy", 11, 0.12)
Dark("DARK5", "Crisp Dim Vignette", "msuf_skin_vignette_crisp", 9, 0.20)

-- Frame: opaque frames over the icon edge, with drop shadow and top gloss.
local function Frame(id, text, band, outer, inner, color, shadow, gloss)
    local layers = {}
    if shadow then layers[#layers + 1] = Shadow(shadow) end
    layers[#layers + 1] = { kind = "band", file = band, outer = outer, inner = inner, color = color }
    Skins.Register(id, { text = text, color = WHITE, gloss = gloss or GLOSS_OFF, layers = layers })
end
Frame("FRAME_SLIM", "Slim Bezel", "msuf_skin_frame_slim", 0.5, 2.5, nil, 0.7, GLOSS_TOP)
Frame("FRAME_BOLD", "Wide Bezel", "msuf_skin_frame_bold", 1, 4, nil, 0.8, GLOSS_TOP)
Frame("FRAME_DOUBLE", "Double Dark Trim", "msuf_skin_frame_double", 0.7, 2.9, { 0, 0, 0, 1 }, 0.5)
Frame("FRAME_DOUBLE_LIGHT", "Double Light Trim", "msuf_skin_frame_double", 0.7, 2.9, WHITE, 0.6)
Frame("FRAME_BEVEL", "Beveled Trim", "msuf_skin_frame_bevel", 0.5, 3, nil, 0.6, GLOSS_TOP)
Frame("FRAME_DARK", "Recessed Bezel", "msuf_skin_frame_dark", 1, 7, nil, 0.7)
Frame("FRAME_CLEAN", "Straight Bezel", "msuf_skin_frame_clean", 0.8, 5, nil, 0.5)
Frame("FRAME_ROUNDED", "Rounded Bezel", "msuf_skin_frame_rounded", 2, 3.5, nil, 0.8, GLOSS_TOP)
Frame("FRAME_STEEL", "Brushed Steel Bezel", "msuf_skin_frame_steel", 2, 3.5, { 0.78, 0.8, 0.84, 1 }, 0.6)

-- Metal: one grey bevelled frame, coloured per metal.
local METALS = {
    { "METAL_SILVER", "Polished Bezel - Cool Silver", { 0.86, 0.88, 0.92, 1 } },
    { "METAL_GOLD", "Polished Bezel - Warm Gold", { 1.0, 0.8, 0.32, 1 } },
    { "METAL_BRONZE", "Polished Bezel - Muted Bronze", { 0.8, 0.55, 0.3, 1 } },
    { "METAL_COPPER", "Polished Bezel - Rose Copper", { 0.88, 0.47, 0.27, 1 } },
    { "METAL_IRON", "Polished Bezel - Slate Gray", { 0.56, 0.56, 0.6, 1 } },
    { "METAL_FEL_IRON", "Polished Bezel - Fern Green", { 0.52, 0.78, 0.36, 1 } },
    { "METAL_COBALT", "Polished Bezel - Cobalt Blue", { 0.36, 0.52, 0.92, 1 } },
    { "METAL_TITANIUM", "Polished Bezel - Ice Silver", { 0.74, 0.84, 0.88, 1 } },
    { "METAL_ADAMANTITE", "Polished Bezel - Graphite Gray", { 0.46, 0.5, 0.58, 1 } },
    { "METAL_SARONITE", "Polished Bezel - Sea Green", { 0.44, 0.7, 0.52, 1 } },
    { "METAL_ELEMENTIUM", "Polished Bezel - Violet", { 0.62, 0.42, 0.92, 1 } },
    { "METAL_KHORIUM", "Polished Bezel - Orchid", { 0.84, 0.46, 0.78, 1 } },
    { "METAL_OBSIDIUM", "Polished Bezel - Charcoal", { 0.32, 0.33, 0.37, 1 } },
}
for i = 1, #METALS do
    local metal = METALS[i]
    Skins.Register(metal[1], {
        text = metal[2],
        color = metal[3],
        gloss = GLOSS_TOP,
        layers = {
            Shadow(0.7),
            { kind = "band", file = "msuf_skin_metal_frame", outer = 1, inner = 4 },
        },
    })
end

-- Pixel: crisp lines, no gloss.
local function Pixel(id, text, layers)
    Skins.Register(id, { text = text, gloss = GLOSS_OFF, layers = layers })
end
Pixel("PIXEL", "Single-Line Outline", { Line(1, "outside") })
Pixel("PIXEL_THICK", "Thick Pixel Outline", { Line(2, "outside") })
Pixel("PIXEL_EDGE", "Inset Pixel Outline", { Line(1, "outside"), Line(1, "inside", { 1, 1, 1, 0.35 }, false) })
Pixel("PIXEL_GLOW", "Shadowed Pixel Outline", { Shadow(0.6), Line(1, "outside") })
Pixel("DREAM", "Feathered Inset", {
    { kind = "band", file = "msuf_skin_vignette_soft", outer = 0, inner = 14, color = { 0, 0, 0, 0.5 } },
    Line(1, "inside"),
})
Pixel("BORDERLESS", "No Trim", {})

