-- Round: ring, gear and orb looks for circular icons.
local function Round(id, text, file, extent, color)
    Skins.Register(id, {
        text = text,
        shape = "CIRCLE",
        color = color,
        gloss = GLOSS_DOME,
        layers = { RoundShadow(0.8), { kind = "quad", file = file, extent = extent } },
    })
end
Round("RING", "Segmented Ring", "msuf_skin_ring_segmented", 4, { 0.86, 0.86, 0.9, 1 })
